def compute(vars):
    changes = [vars["v1"], vars["v2"], vars["v3"]]
    qualifying_count = sum(1 for change in changes if change < 50)
    return {
        "value": qualifying_count,
        "trace": {
            "changes": changes,
            "threshold": 50,
            "qualifying_count": qualifying_count,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "items"
            }
        }
    }
